-- ============================================================================
-- table_comments.sql — 全库表注释/字段注释补全脚本（幂等，可重复执行）
-- ============================================================================
-- 用途：给 qztgo 库所有【无注释】的表/字段补上中文注释（已有注释一律不动）。
-- 注释来源（优先级）：Go model 的 gorm:"comment:" tag > model struct 的 Go doc 注释
--   > 通用字段兜底（id/created_at/updated_at/deleted_at/sort/remark...）
--   > 手工补充（连接表/casbin/sys_api/sys_menu 等无 comment tag 的字段）。
-- 安全性：字段注释用 ALTER TABLE ... MODIFY COLUMN，列定义从 information_schema
--   精确重建（保留 type/NOT NULL/DEFAULT/AUTO_INCREMENT/on update 精度），仅追加 COMMENT。
--   不会改类型、不会丢约束。表注释用 ALTER TABLE ... COMMENT（安全）。
-- 幂等：只处理 table_comment/column_comment 为空的；已有注释的不动，可安全重复执行。
-- 执行方式（任选其一）：
--   1) mysql 客户端：  mysql -h <host> -u <user> -p qztgo < docs/sql/table_comments.sql
--   2) DBX MCP：       开持久 session，逐条执行（CREATE TEMP/INSERT/CREATE PROC/CALL/清理）。
-- 注意：
--   - VIRTUAL/STORED 生成列不能用 MODIFY 改注释，本脚本跳过（当前库无此类列）。
--   - DEFAULT_GENERATED 时间列（CURRENT_TIMESTAMP）已正确处理精度。
--   - 映射数据快照于 2026-08-13；model 新增字段后需重新生成 _tc 映射（见文末说明）。
--   - 临时表 _tc/_tc_spec/_tc_glob 仅本次连接可见，脚本结束自动清理。
-- ============================================================================

DROP TEMPORARY TABLE IF EXISTS _tc;
-- 自动生成: model 注释映射临时表 setup（供 DBX session 使用）
DROP TEMPORARY TABLE IF EXISTS _tc;
CREATE TEMPORARY TABLE _tc (t VARCHAR(64) NOT NULL, c VARCHAR(64), cm VARCHAR(500), tc VARCHAR(500));
