-- 派生表（避免临时表在同一查询被 JOIN 两次的 MySQL 限制）
DROP TEMPORARY TABLE IF EXISTS _tc_spec;
DROP TEMPORARY TABLE IF EXISTS _tc_glob;
CREATE TEMPORARY TABLE _tc_spec AS SELECT t,c,cm,tc FROM _tc WHERE t<>'*GLOBAL*';
CREATE TEMPORARY TABLE _tc_glob AS SELECT c,cm FROM _tc WHERE t='*GLOBAL*';

-- 幂等补注释存储过程：仅对当前【无注释】的表/字段补，已有注释不动。
-- 列定义从 information_schema 精确重建（保留 type/NOT NULL/DEFAULT/AUTO_INCREMENT/on update 精度），仅追加 COMMENT。
-- 跳过 VIRTUAL/STORED 生成列（不可用 MODIFY 改注释）。
DROP PROCEDURE IF EXISTS _regen_comments;
CREATE PROCEDURE _regen_comments()
BEGIN
  DECLARE done INT DEFAULT 0;
  DECLARE v_sql TEXT;
  DECLARE cur1 CURSOR FOR
    SELECT CONCAT('ALTER TABLE `', t.table_name, '` COMMENT=''', REPLACE(m.tc,'''',''''''), '''')
    FROM information_schema.tables t
    JOIN _tc_spec m ON m.t=t.table_name AND m.c IS NULL AND m.tc IS NOT NULL
    WHERE t.table_schema=DATABASE() AND (t.table_comment='' OR t.table_comment IS NULL);
  DECLARE cur2 CURSOR FOR
    SELECT CONCAT('ALTER TABLE `', c.table_name, '` MODIFY COLUMN `', c.column_name, '` ',
      c.column_type, IF(c.is_nullable='NO',' NOT NULL',''),
      CASE WHEN c.extra LIKE '%auto_increment%' THEN ' AUTO_INCREMENT'
           WHEN c.column_default IS NULL THEN ''
           WHEN c.column_default LIKE 'CURRENT_TIMESTAMP%' THEN CONCAT(' DEFAULT ',c.column_default)
           WHEN c.data_type IN ('int','bigint','tinyint','smallint','mediumint','decimal','float','double','bit') THEN CONCAT(' DEFAULT ',c.column_default)
           ELSE CONCAT(' DEFAULT ''',REPLACE(c.column_default,'''',''''''),'''') END,
      IF(c.extra LIKE '%on update%', CONCAT(' ON UPDATE', TRIM(SUBSTRING_INDEX(c.extra,'on update',-1))), ''),
      ' COMMENT ''',REPLACE(COALESCE(s.cm,g.cm),'''',''''''),'''')
    FROM information_schema.columns c
    LEFT JOIN _tc_spec s ON s.t=c.table_name AND s.c=c.column_name AND s.cm IS NOT NULL
    LEFT JOIN _tc_glob g ON g.c=c.column_name
    WHERE c.table_schema=DATABASE() AND (c.column_comment='' OR c.column_comment IS NULL)
      AND c.extra NOT LIKE '%VIRTUAL%' AND c.extra NOT LIKE '%STORED%'
      AND COALESCE(s.cm,g.cm) IS NOT NULL
    ORDER BY c.table_name, c.ordinal_position;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done=1;
  DECLARE CONTINUE HANDLER FOR SQLEXCEPTION BEGIN END;
  OPEN cur1;
  l1: LOOP
    FETCH cur1 INTO v_sql; IF done=1 THEN LEAVE l1; END IF;
    SET @s=v_sql; PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
  END LOOP; CLOSE cur1;
  SET done=0;
  OPEN cur2;
  l2: LOOP
    FETCH cur2 INTO v_sql; IF done=1 THEN LEAVE l2; END IF;
    SET @s=v_sql; PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
  END LOOP; CLOSE cur2;
END;

CALL _regen_comments();

DROP PROCEDURE IF EXISTS _regen_comments;
DROP TEMPORARY TABLE IF EXISTS _tc;
DROP TEMPORARY TABLE IF EXISTS _tc_spec;
DROP TEMPORARY TABLE IF EXISTS _tc_glob;

